.product { max-width: 1200px; margin: 0 auto; padding: 16px 32px 0; }
.breadcrumb ol { list-style: none; display: flex; gap: 8px; padding: 0; margin: 0 0 16px; font-size: 14px; color: var(--muted); }
.breadcrumb li + li::before { content: '›'; margin-right: 8px; }
.breadcrumb a { color: var(--muted); }
.product-hero { display: grid; grid-template-columns: 1.4fr 1fr; gap: 48px; align-items: start; }
@media (max-width: 860px) { .product-hero { grid-template-columns: 1fr; } }

/* Gallery */
.gallery-stage { position: relative; background: #eceef1; border-radius: 6px; overflow: hidden; }
.gallery-stage img { display: block; width: 100%; height: auto; aspect-ratio: 520 / 320; }
.gallery-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--line);
  background: #fff; cursor: pointer; font-size: 18px;
}
.gallery-arrow.prev { left: 12px; }
.gallery-arrow.next { right: 12px; }
.gallery-counter {
  position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.7); color: #fff; padding: 3px 10px; border-radius: 12px; font-size: 13px;
}

/* Buy box */
.buybox h1 { font-size: 30px; margin: 0 0 8px; }
.price-row { display: flex; align-items: center; gap: 8px; font-size: 22px; font-weight: 700; }
.price-info-wrap { position: relative; display: inline-block; }
.info-button {
  width: 20px; height: 20px; border-radius: 50%; border: 1px solid var(--muted);
  background: #fff; font-size: 12px; font-style: italic; cursor: help; padding: 0;
}
.tooltip {
  position: absolute; left: 50%; bottom: calc(100% + 8px); transform: translateX(-50%);
  white-space: nowrap; background: var(--ink); color: #fff; padding: 6px 10px; border-radius: 4px;
  font-size: 13px; font-weight: 400; z-index: 5;
}
.description { color: var(--muted); line-height: 1.5; }

.option { margin: 18px 0; position: relative; }
.option-label { display: block; font-weight: 600; margin-bottom: 6px; }
.option-toggle {
  background: none; border: 0; padding: 0; cursor: pointer; font-size: 16px; text-align: left;
}
.option-toggle::after { content: ' ▾'; color: var(--muted); }
.option-toggle strong { font-weight: 700; }

.swatches { display: flex; gap: 10px; margin-top: 10px; }
.swatch {
  appearance: none; -webkit-appearance: none; width: 32px; height: 32px; margin: 0;
  border-radius: 50%; background: var(--swatch); border: 1px solid #00000022; cursor: pointer;
}
.swatch:checked { box-shadow: 0 0 0 2px #fff, 0 0 0 4px var(--ink); }

.size-row { display: flex; align-items: baseline; gap: 16px; }
.link-button { background: none; border: 0; padding: 0; color: var(--accent); text-decoration: underline; cursor: pointer; }
.size-list {
  position: absolute; z-index: 4; top: 36px; left: 0; right: 0; margin: 0; padding: 6px;
  list-style: none; background: #fff; border: 1px solid var(--line); border-radius: 6px;
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; box-shadow: 0 8px 24px #0002;
}
.size-option-item {
  border: 1px solid var(--line); border-radius: 4px; padding: 8px 6px; text-align: center; cursor: pointer;
  display: flex; flex-direction: column; gap: 2px; font-weight: 600; font-size: 14px;
}
.size-option-item:hover, .size-option-item:focus-visible { border-color: var(--ink); outline: none; }
.size-option-item.selected { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }
.size-option-item .eu { font-weight: 400; color: var(--muted); font-size: 12px; }
.size-option-item.sold-out { color: #9a9ea5; background: var(--panel); cursor: not-allowed; text-decoration: line-through; }
.sold-out-tag { text-decoration: none; font-size: 11px; }

.quantity { margin: 18px 0; }
.stepper { display: inline-flex; border: 1px solid var(--line); border-radius: 4px; overflow: hidden; }
.stepper button { width: 40px; height: 40px; border: 0; background: #fff; cursor: pointer; font-size: 18px; }
.stepper button:disabled { color: #aab; cursor: not-allowed; }
.stepper input {
  width: 64px; text-align: center; border: 0; border-left: 1px solid var(--line); border-right: 1px solid var(--line);
  -moz-appearance: textfield;
}

.actions { display: flex; gap: 12px; align-items: stretch; }
.primary, .secondary {
  border-radius: 24px; padding: 14px 24px; font-weight: 700; cursor: pointer; border: 1px solid var(--accent);
}
.primary { background: var(--accent); color: #fff; flex: 1; }
.secondary { background: #fff; color: var(--accent); padding: 8px 16px; font-size: 14px; }
.secondary:disabled { opacity: 0.5; cursor: not-allowed; }
.wishlist {
  border: 1px solid var(--line); background: #fff; border-radius: 24px; padding: 0 18px; cursor: pointer; font-weight: 600;
}
.wishlist.active { color: #c4253d; border-color: #c4253d; }

.message { margin: 14px 0 0; padding: 10px 14px; border-radius: 4px; }
.message.error { background: #fdecec; color: #8a1b1b; }
.message.success { background: #e9f6ec; color: #1d5e2b; }

/* Modal */
.modal-backdrop {
  position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); display: flex;
  align-items: center; justify-content: center; padding: 16px; z-index: 50;
}
.modal {
  background: #fff; border-radius: 8px; width: min(560px, 100%); max-height: 90vh; overflow: auto; padding: 24px;
}
.modal-head { display: flex; justify-content: space-between; align-items: center; }
.modal-head h2 { margin: 0; font-size: 22px; }
.modal-close { background: none; border: 0; font-size: 28px; cursor: pointer; line-height: 1; }
.guide-form { display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-end; margin: 16px 0; }
.guide-form label { display: flex; flex-direction: column; gap: 4px; font-weight: 600; }
.guide-form input[type='number'] { padding: 8px; border: 1px solid var(--line); border-radius: 4px; width: 140px; }
.guide-form fieldset { border: 0; padding: 0; margin: 0; display: flex; gap: 12px; }
.guide-form legend { font-weight: 600; padding: 0; margin-bottom: 4px; }
.radio-label { display: inline-flex; flex-direction: row !important; gap: 4px; align-items: center; font-weight: 400 !important; }
.primary.guide-submit { flex: none; }
.guide-form .primary { flex: none; padding: 10px 18px; }
.guide-result { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin-bottom: 12px; }
.guide-error { color: #8a1b1b; }
.chart { width: 100%; border-collapse: collapse; margin-top: 12px; font-size: 14px; }
.chart th, .chart td { border-bottom: 1px solid var(--line); padding: 6px 8px; text-align: left; }

/* Sections below the buy box */
.questions, .more-info { margin: 48px 0 0; border-top: 1px solid var(--line); padding-top: 24px; }
.questions h2, .more-info h2 { font-size: 22px; margin: 0 0 12px; }
.faq-item { border-bottom: 1px solid var(--line); }
.faq-question {
  width: 100%; display: flex; justify-content: space-between; align-items: center; gap: 12px;
  background: none; border: 0; padding: 16px 0; text-align: left; font-weight: 600; font-size: 16px; cursor: pointer;
}
.faq-answer p { margin: 0 0 16px; color: var(--muted); line-height: 1.5; }

.tablist { display: flex; gap: 0; border-bottom: 1px solid var(--line); }
.tab {
  flex: 1; background: none; border: 0; border-bottom: 3px solid transparent; padding: 12px 8px;
  font-weight: 600; cursor: pointer; font-size: 16px;
}
.tab.active { border-bottom-color: var(--ink); }
.tabpanel { padding: 20px 0 32px; line-height: 1.6; }
.tabpanel ul { padding-left: 20px; margin: 0; }
.tabpanel blockquote { margin: 12px 0; padding-left: 12px; border-left: 3px solid var(--line); }
.tabpanel cite { color: var(--muted); font-style: normal; font-size: 14px; }

/* Footer */
.site-footer { background: var(--panel); margin-top: 32px; padding: 40px 32px 24px; }
.footer-cols { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
@media (max-width: 760px) { .footer-cols { grid-template-columns: 1fr; } }
.site-footer h2 { font-size: 16px; margin: 0 0 10px; }
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 6px; }
.site-footer p { margin: 0 0 6px; font-size: 14px; }
.social { grid-auto-flow: column; justify-content: start; gap: 16px !important; }
.copyright { max-width: 1200px; margin: 24px auto 0; color: var(--muted); font-size: 13px; }
EOF
